#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=1;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader amzt_xDistBuf;
float4 amzSample_xDistBuf(float2 uv) { return float4(amzt_xDistBuf.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_xDistBuf(uv);return float4(0.0); }
uniform float amzp_b0size;
layout(color) uniform half4 amzp_b0color;
        float2 encodeFloat(float v) {
             float2 enc = fract(float2(1.0, 255.0)*v);
            enc.x -= enc.y/255.0;
            return enc;
        }
        float decodeFloat(float2 v) {
            return dot(v,float2(1.0,1.0/255.0));
        }
        struct Border {
            int direction;
            float amzLocal_size;
            float4 color;
        };
        void amzRender() {
            float radius=amzp_b0size*1.0;
            int from = -amzIntMax(1,int(radius));
            int to = amzIntMax(1,int(radius));
            float px = 1.0 / 2048.0;
            float2 fullViewSize = getTexSize((screen.zw/1.0));
            float py = 1.0 / (2048.0 / (fullViewSize.x/fullViewSize.y));
            if( amzPass==0 ) {
                float nearestInside = 16383.0;
                for(int i=from; i<to; i++ ) {
                    float x = float(i);
                    float4 sample = amzTexture(0,float2(amzScreenNorm().s + x*(px/1.0),amzScreenNorm().t));
                    float xdistIn = sample.a < 0.003 ? abs(x) : radius*2.0;
                    nearestInside = min(nearestInside,xdistIn);
                }
                amzOutput = float4(0.,0.,encodeFloat(nearestInside/16383.0));
            } else {
                float nearestInside = 16383.0;
                for(int i=from; i<to; i++ ) {
                    float y = float(i);
                    float4 sample = amzTexture(1,float2(amzScreenNorm().s,amzScreenNorm().t + y*(py/1.0)));
                    float xdistIn = decodeFloat(sample.ba) * 16383.0;
                    float ydist = abs(y);
                    float distIn = length(float2(xdistIn,ydist));
                    nearestInside = min(nearestInside,distIn);
                }
                float4 original = amzTexture(0,amzScreenNorm().st);
                float4 result = original;
                if( amzp_b0size > 0.003 ) {
                        float4 c = mix(amzp_b0color, float4(0.0), smoothstep(1.0-1.5/amzp_b0size,1.0,nearestInside/(amzp_b0size/1.0))) * original.a;
                        result = c + result*(1.0-c.a);
                }
                amzOutput = result;
            }
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

